   161	static ptrdiff_t
   162	write_pool_block(mrb_state *mrb, const mrb_irep *irep, uint8_t *buf)
   163	{
   164	  int pool_no;
   165	  uint8_t *cur = buf;
   166	  mrb_int len;
   167	  const char *ptr;
   168	
   169	  cur += uint16_to_bin(irep->plen, cur); /* number of pool */
   170	
   171	  for (pool_no = 0; pool_no < irep->plen; pool_no++) {
   172	    int ai = mrb_gc_arena_save(mrb);
   173	
   174	    switch (irep->pool[pool_no].tt) {
   175	    case IREP_TT_INT64:
   176	#if defined(MRB_64BIT) || defined(MRB_INT64)
   177	      {
   178	        int64_t i = irep->pool[pool_no].u.i64;
   179	        if (i < INT32_MIN || INT32_MAX < i) {
   180	          cur += uint8_to_bin(IREP_TT_INT64, cur); /* data type */
   181	          cur += uint32_to_bin((uint32_t)((i>>32) & 0xffffffff), cur); /* i64 hi */
   182	          cur += uint32_to_bin((uint32_t)((i    ) & 0xffffffff), cur); /* i64 lo */
   183	        }
   184	        else {
   185	          cur += uint8_to_bin(IREP_TT_INT32, cur); /* data type */
   186	          cur += uint32_to_bin(irep->pool[pool_no].u.i32, cur); /* i32 */
   187	        }
   188	      }
   189	      break;
   190	#endif
   191	    case IREP_TT_INT32:
   192	      cur += uint8_to_bin(IREP_TT_INT32, cur); /* data type */
   193	      cur += uint32_to_bin(irep->pool[pool_no].u.i32, cur); /* i32 */
   194	      break;
   195	
   196	    case IREP_TT_BIGINT:
   197	      cur += uint8_to_bin(IREP_TT_BIGINT, cur); /* data type */
   198	      len = irep->pool[pool_no].u.str[0];
   199	      memcpy(cur, irep->pool[pool_no].u.str, (size_t)len+2);
   200	      cur += len+2;
   201	      break;
   202	
   203	    case IREP_TT_FLOAT:
   204	      cur += uint8_to_bin(IREP_TT_FLOAT, cur); /* data type */
   205	#ifndef MRB_NO_FLOAT
   206	      {
   207	        dump_float(mrb, cur,irep->pool[pool_no].u.f);
   208	        cur += sizeof(double);
   209	      }
   210	#else
   211	      cur += uint16_to_bin(0, cur); /* zero length */
   212	#endif
   213	      break;
   214	
   215	    default: /* string */
   216	      cur += uint8_to_bin(IREP_TT_STR, cur); /* data type */
   217	      ptr = irep->pool[pool_no].u.str;
   218	      len = irep->pool[pool_no].tt>>2;
   219	      mrb_assert_int_fit(mrb_int, len, uint16_t, UINT16_MAX);
   220	      cur += uint16_to_bin((uint16_t)len, cur); /* data length */
   221	      memcpy(cur, ptr, (size_t)len);
   222	      cur += len;
   223	      *cur++ = '\0';
   224	      break;
   225	    }
   226	    mrb_gc_arena_restore(mrb, ai);
   227	  }
   228	
   229	  return cur - buf;
   230	}
